1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const LOYALTY_DISCOUNT_RATE = 0.2;
7	const LOYALTY_THRESHOLD_YEARS = 2;
8	const FOLLOWUP_CONTRACT_DISCOUNT_RATE = 0.15;
9	const COMPONENT_BLOCK_BASE = 60;
10	const COMPONENT_BLOCK_SIZE = 3;
11	const DEDUCTIBLE_PER_DAMAGE = 100;
12	const CAP_MULTIPLIER = 2;
13	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
14	const HIGH_ENCHANTMENT_PAYOUT_RATE = 0.5;
15	
16	const BASE_PREMIUM: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	};
24	
25	const INSURANCE_VALUE: Record<string, number> = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	  rune: 250,
31	  moonstone: 250,
32	};
33	
34	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
35	
36	type Item = { type: string; cursed?: boolean; enchantment?: number; material?: string };
37	type Customer = { yearsWithMHPCO: number };
38	type QuoteStep = { op: "quote"; items: Item[] };
39	type Damage = { itemType: string; amount: number };
40	type ClaimStep = {
41	  op: "claim";
42	  policy: number;
43	  incident: { cause: string; damages: Damage[] };
44	};
45	type Step = QuoteStep | ClaimStep;
46	type Scenario = { customer: Customer; steps: Step[] };
47	
48	type QuoteResult = { premium: number };
49	type ClaimResult = { payout: number; remainingCap: number };
50	type StepResult = QuoteResult | ClaimResult;
51	
52	type Policy = { items: Item[]; remainingCap: number };
53	
54	const countBy = <T>(values: T[], keyOf: (value: T) => string): Map<string, number> =>
55	  values.reduce(
56	    (counts, value) => counts.set(keyOf(value), (counts.get(keyOf(value)) ?? 0) + 1),
57	    new Map<string, number>(),
58	  );
59	
60	const countByType = (items: Item[]): Map<string, number> =>
61	  countBy(items, (item) => item.type);
62	
63	const basePremiumForGroup = (type: string, count: number): number =>
64	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
65	    ? COMPONENT_BLOCK_BASE
66	    : count * BASE_PREMIUM[type];
67	
68	const basePremiumForItems = (items: Item[]): number =>
69	  [...countByType(items)].reduce(
70	    (sum, [type, count]) => sum + basePremiumForGroup(type, count),
71	    0,
72	  );
73	
74	const surchargeRateForItem = (item: Item): number =>
75	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
76	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
77	
78	const itemSurcharges = (items: Item[]): number =>
79	  items.reduce(
80	    (sum, item) => sum + BASE_PREMIUM[item.type] * surchargeRateForItem(item),
81	    0,
82	  );
83	
84	const roundUpForInsurer = (premium: number): number => Math.ceil(premium);
85	const roundDownForInsurer = (payout: number): number => Math.floor(payout);
86	
87	const loyaltyDiscountRate = (customer: Customer): number =>
88	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_DISCOUNT_RATE : 0;
89	
90	const followupDiscountRate = (quoteIndex: number): number =>
91	  quoteIndex > 0 ? FOLLOWUP_CONTRACT_DISCOUNT_RATE : 0;
92	
93	const withPolicyWideModifiers = (
94	  base: number,
95	  customer: Customer,
96	  quoteIndex: number,
97	): number =>
98	  base +
99	  base * FIRST_INSURANCE_SURCHARGE_RATE -
100	  base * loyaltyDiscountRate(customer) -
101	  base * followupDiscountRate(quoteIndex);
102	
103	const quotePremium = (
104	  { items }: QuoteStep,
105	  customer: Customer,
106	  quoteIndex: number,
107	): number =>
108	  roundUpForInsurer(
109	    withPolicyWideModifiers(basePremiumForItems(items), customer, quoteIndex) +
110	      itemSurcharges(items),
111	  ) + PROCESSING_FEE;
112	
113	const insuranceSumFor = (items: Item[]): number =>
114	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
115	
116	const policyFrom = (items: Item[]): Policy => ({
117	  items,
118	  remainingCap: insuranceSumFor(items) * CAP_MULTIPLIER,
119	});
120	
121	const reimbursementRateFor = (item: Item): number =>
122	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_PAYOUT_THRESHOLD ? HIGH_ENCHANTMENT_PAYOUT_RATE : 1;
123	
124	const payoutForDamage = (item: Item, amount: number): number =>
125	  roundDownForInsurer(Math.max(0, amount * reimbursementRateFor(item) - DEDUCTIBLE_PER_DAMAGE));
126	
127	const findInsuredItem = (items: Item[], itemType: string): Item =>
128	  items.find((item) => item.type === itemType)!;
129	
130	const totalPayoutFor = ({ items }: Policy, damages: Damage[]): number =>
131	  damages.reduce(
132	    (sum, { itemType, amount }) => sum + payoutForDamage(findInsuredItem(items, itemType), amount),
133	    0,
134	  );
135	
136	const validateDamages = (policy: Policy, damages: Damage[]): void => {
137	  const insuredCounts = countByType(policy.items);
138	  countBy(damages, (damage) => damage.itemType).forEach((damageCount, itemType) => {
139	    if (damageCount > (insuredCounts.get(itemType) ?? 0)) {
140	      throw new Error(`Damage entries for ${itemType} exceed insured count`);
141	    }
142	  });
143	};
144	
145	const applyClaim = (
146	  policy: Policy,
147	  damages: Damage[],
148	): { policy: Policy; result: ClaimResult } => {
149	  validateDamages(policy, damages);
150	  const payout = Math.min(totalPayoutFor(policy, damages), policy.remainingCap);
151	  const remainingCap = policy.remainingCap - payout;
152	  return { policy: { ...policy, remainingCap }, result: { payout, remainingCap } };
153	};
154	
155	const handleQuote = (
156	  step: QuoteStep,
157	  customer: Customer,
158	  policies: Map<number, Policy>,
159	  index: number,
160	): QuoteResult => {
161	  const premium = quotePremium(step, customer, policies.size);
162	  policies.set(index, policyFrom(step.items));
163	  return { premium };
164	};
165	
166	const handleClaim = (
167	  step: ClaimStep,
168	  policies: Map<number, Policy>,
169	): ClaimResult => {
170	  const { policy, result } = applyClaim(policies.get(step.policy)!, step.incident.damages);
171	  policies.set(step.policy, policy);
172	  return result;
173	};
174	
175	export const runScenario = ({ customer, steps }: Scenario): { results: StepResult[] } => {
176	  const policies = new Map<number, Policy>();
177	  const results = steps.map((step, index) =>
178	    step.op === "quote"
179	      ? handleQuote(step, customer, policies, index)
180	      : handleClaim(step, policies),
181	  );
182	  return { results };
183	};
